-- ============================================================
--  Mujunakuy (PO-005) — RHE reales (58 recibos por honorarios)
--  Extraídos del PDF maestro. 18 personas · suma S/ 151,325.00 · retención 0
--  (suspensión de 4ta activa). Se resuelve cada persona por su DNI (o RUC).
--
--  Idempotente: no reinserta un RHE ya cargado (misma persona + número).
--  Los que no encuentren persona NO se insertan; salen en el reporte final
--  para que crees a esas personas y vuelvas a correr el script.
--
--  Los ejes (actividad del cronograma · rubro del presupuesto) quedan vacíos
--  y se asignan después en la pantalla del fondo.
-- ============================================================

create temp table _rhe_carga (
  dni text, ruc text, nombre text, numero text, fecha date,
  monto numeric(12,2), retencion numeric(12,2), concepto text
) on commit drop;


-- ── Insertar solo los RHE cuya persona existe (por DNI o RUC) ──
select p.id, f.id, c.numero, c.fecha, c.monto, c.retencion, c.concepto
  from _rhe_carga c
  join personas p on (p.ruc_dni = c.dni or p.ruc_dni = c.ruc)
  cross join (select id from postulaciones where codigo = 'PO-005') f
 where not exists (
   select 1 from rhe r where r.persona_id = p.id and r.numero = c.numero
 );

-- ── Reporte 1: personas del PDF que NO existen aún (créalas y re-corre) ──
select c.dni, max(c.nombre) as nombre, count(*) as rhe, sum(c.monto) as total_s
  from _rhe_carga c
  left join personas p on (p.ruc_dni = c.dni or p.ruc_dni = c.ruc)
 where p.id is null
 group by c.dni
 order by total_s desc;

-- ── Reporte 2: lo que quedó cargado en el fondo ──
select count(*) as rhe_cargados, sum(r.monto) as total_s
  from rhe r
  join postulaciones p on p.id = r.postulacion_id
 where p.codigo = 'PO-005';
